import React from 'react';
import { Thermometer, Gauge, Activity, Zap, Wind, Droplets, Radio, TrendingUp, AlertTriangle } from 'lucide-react';

const LiveSensorWidgets = () => {
  const sensorWidgets = [
    { title: 'Temperature', val: '52.4 °C', range: '40 – 70 °C', status: 'Nominal', trend: '↑ 0.2°C', icon: Thermometer, color: '#088395' },
    { title: 'Loom Speed (RPM)', val: '1,080 RPM', range: '900 – 1,200 RPM', status: 'Optimal', trend: 'Stable', icon: Gauge, color: '#10b981' },
    { title: 'Vibration', val: '0.18 mm/s', range: '< 0.35 mm/s', status: 'Low Risk', trend: '↓ 0.02', icon: Activity, color: '#10b981' },
    { title: 'Power Consumption', val: '16.4 kW', range: '12 – 20 kW', status: 'Efficient', trend: '↓ 1.2 kW', icon: Zap, color: '#7AB2B2' },
    { title: 'Air Pressure', val: '6.2 Bar', range: '5.5 – 7.0 Bar', status: 'Stable', trend: 'Nominal', icon: Wind, color: '#088395' },
    { title: 'Ambient Humidity', val: '65% RH', range: '60 – 70% RH', status: 'Ideal Weaving', trend: 'Controlled', icon: Droplets, color: '#088395' },
    { title: 'Yarn Tension', val: '18.2 cN', range: '15 – 22 cN', status: 'Nominal', trend: 'Nominal', icon: Radio, color: '#10b981' },
    { title: 'Motor Current', val: '32.5 A', range: '25 – 40 A', status: 'Nominal', trend: 'Stable', icon: Zap, color: '#7AB2B2' },
  ];

  return (
    <div className="glass-card" style={{ padding: '1.5rem', marginBottom: '1.75rem' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
        <div>
          <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Radio size={20} style={{ color: 'var(--accent-primary)' }} /> Live Telemetry Sensor Stream (136 Feeds)
          </h3>
          <p style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: '600', marginTop: '2px' }}>
            Real-Time Transducer Signal Monitoring Across All Weaving Looms
          </p>
        </div>
        <span className="badge badge-running">100% Signal Integrity</span>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '1.1rem' }}>
        {sensorWidgets.map((sw, idx) => {
          const Icon = sw.icon;
          return (
            <div
              key={idx}
              style={{
                background: 'var(--bg-primary)',
                borderRadius: '8px',
                padding: '1rem',
                border: '1px solid var(--border-subtle)',
                display: 'flex',
                flexDirection: 'column',
                justify: 'space-between',
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                <span style={{ fontSize: '0.78rem', fontWeight: '800', color: 'var(--text-muted)' }}>{sw.title}</span>
                <Icon size={16} style={{ color: sw.color }} />
              </div>

              <div>
                <div style={{ fontSize: '1.4rem', fontWeight: '900', color: 'var(--text-primary)' }}>{sw.val}</div>
                <div style={{ fontSize: '0.72rem', color: 'var(--text-secondary)', fontWeight: '700', marginTop: '2px' }}>
                  Normal Range: {sw.range}
                </div>
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.65rem', paddingTop: '0.5rem', borderTop: '1px solid var(--border-subtle)', fontSize: '0.7rem' }}>
                <span style={{ color: 'var(--status-running)', fontWeight: '800' }}>● {sw.status}</span>
                <span style={{ color: 'var(--text-muted)', fontWeight: '600' }}>{sw.trend}</span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default LiveSensorWidgets;
